// ?setFlipRecursive@W3DTerrainBackground@@IAEXHHH@Z
// partial score=0.1869 date=2026-10-15
// cl: /DNDEBUG /MD
//
// Retail 0x00729700: W3DTerrainBackground::setFlipRecursive(Int, Int, Int),
// the BFME form of ZH's quadtree flip pass. Called three times from itself
// (the fourth quadrant is the tail call) and from setFlip 0x00729F00
// through the ?j_0001b5f9 stub with (0, 0, m_width).
// BFME adds a step (+0x78) for the scan, a per-cell occupancy check and a
// flip-bit compare against the corner, and marks corners only where
// isEdgeAligned (0x007288B0) allows it.

typedef bool Bool;
typedef int Int;
typedef unsigned short UnsignedShort;

class Rva00729370BitPlane
{
public:
	bool test(int x, int y) const;
};

class BfmeMaskAX
{
public:
	void bfmeMarkAX(int x, int y, unsigned char value);
};

class WorldHeightMap
{
public:
	unsigned char m_pad00[0x08];
	Int m_width;
	Int m_height;
	unsigned char m_pad10[0x10];
	Int m_dataSize;
	UnsignedShort *m_data;
	unsigned char m_pad28[0x0c];
	Int m_flipStride;
	unsigned char m_pad38[0x18];
	unsigned char *m_flipBegin;
	unsigned char *m_flipEnd;
	unsigned char m_pad58[0x3c];
	void **m_cells94;
	unsigned char m_pad98[0x120e0 - 0x98];
	Int m_cellOriginX;
	Int m_cellOriginY;

	UnsignedShort getHeight(Int x, Int y)
	{
		Int ndx = (y * m_width) + x;
		if ((ndx >= 0) && (ndx < m_dataSize) && m_data)
			return m_data[ndx];
		return 0;
	}

	Bool hasCell(Int x, Int y)
	{
		Int ndx = (y + m_cellOriginY) * m_width + m_cellOriginX + x;
		if ((ndx >= 0) && (ndx < m_dataSize))
			return m_cells94[ndx] != 0;
		return false;
	}

	Bool getFlipState(Int x, Int y)
	{
		if (x < 0 || y < 0 || y >= m_height || x >= m_width)
			return false;
		Int ndx = m_flipStride * y + (x >> 3);
		if ((unsigned)ndx >= (unsigned)(m_flipEnd - m_flipBegin))
			return false;
		return (m_flipBegin[ndx] & (1 << (x & 7))) != 0;
	}

	Bool getFlipStateCall(Int x, Int y)
	{
		return ((Rva00729370BitPlane *)this)->test(x, y);
	}

	void setFlipState(Int x, Int y, Bool value)
	{
		((BfmeMaskAX *)this)->bfmeMarkAX(x, y, value);
	}
};

class W3DTerrainBackground
{
public:
	Bool isEdgeAligned(Int x, Int y, Int width);

protected:
	void setFlipRecursive(Int xOffset, Int yOffset, Int width);

private:
	unsigned char m_pad00[0x40];
	Int m_xOrigin;
	Int m_yOrigin;
	Int m_width;
	WorldHeightMap *m_map;
	unsigned char m_pad50[0x28];
	Int m_78;
};

// ?setFlipRecursive@W3DTerrainBackground@@IAEXHHH@Z
void W3DTerrainBackground::setFlipRecursive(Int xOffset, Int yOffset, Int width)
{
	Int limitX = m_map->m_width - 1;
	Int limitY = m_map->m_height - 1;
	Int i, j;
	Bool match = true;
	Int minX = m_xOrigin + xOffset;
	Int minY = m_yOrigin + yOffset;
	Int cornerHeight = m_map->getHeight(minX, minY);
	WorldHeightMap *map = m_map;
	Bool cornerFlip = map->getFlipStateCall(minX, minY);

	for (i = 0; i <= width; i += m_78) {
		for (j = 0; j <= width; j += m_78) {
			Int k = minX + i;
			k = k < limitX ? k : limitX;
			Int l = minY + j;
			l = l < limitY ? l : limitY;
			if (cornerHeight != map->getHeight(k, l)) {
				match = false;
				break;
			}
			if (map->hasCell(k, l)) {
				match = false;
				break;
			}
			if (i < width && j < width && map->getFlipState(k, l) != cornerFlip) {
				match = false;
				break;
			}
		}
	}

	if (width == m_78) {
		match = true;
	}

	if (match) {
		Int maxX = minX + width;
		maxX = maxX < limitX ? maxX : limitX;
		Int maxY = minY + width;
		maxY = maxY < limitY ? maxY : limitY;
		Int yOrigin = m_yOrigin;
		Int left = minX - m_xOrigin;
		Int bottom = maxY - yOrigin;
		Bool corner3 = isEdgeAligned(left, bottom, width);
		Int right = maxX - m_xOrigin;
		Bool corner2 = isEdgeAligned(right, bottom, width);
		Int top = minY - yOrigin;
		Bool corner1 = isEdgeAligned(right, top, width);
		Bool corner0 = isEdgeAligned(left, top, width);
		if (corner0)
			m_map->setFlipState(minX, minY, true);
		if (corner1)
			m_map->setFlipState(maxX, minY, true);
		if (corner2)
			m_map->setFlipState(maxX, maxY, true);
		if (corner3)
			m_map->setFlipState(minX, maxY, true);
		return;
	}
	Int halfWidth = width / 2;
	setFlipRecursive(xOffset, yOffset, halfWidth);
	setFlipRecursive(xOffset, yOffset + halfWidth, halfWidth);
	setFlipRecursive(xOffset + halfWidth, yOffset, halfWidth);
	setFlipRecursive(xOffset + halfWidth, yOffset + halfWidth, halfWidth);
}
